// Telefon numarası için özel tasarım oluşturan metodimport 'package:easy_localization/easy_localization.dart';import 'package:flutter/cupertino.dart';import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:url_launcher/url_launcher_string.dart';import '../../util/parsers.dart';Widget buildPhoneRecord(BuildContext context, String phoneNumber,[VoidCallback? onDeleted]) {  return Column(    mainAxisSize: MainAxisSize.min,    children: [      Container(        margin: const EdgeInsets.symmetric(vertical: 6),        clipBehavior: Clip.antiAlias,        decoration: BoxDecoration(          color: Theme.of(context).colorScheme.surfaceContainerLow,          borderRadius: BorderRadius.circular(20),          border: Border.all(            color: Theme.of(context).colorScheme.outlineVariant.withValues(alpha: 0.6),          ),        ),        child: Column(          children: [            Container(              padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),              decoration: BoxDecoration(                color: Colors.transparent,              ),              child: Row(                children: [                  Icon(Icons.phone, color: Colors.green),                  const SizedBox(width: 12),                  Text(                    'nfc.scan.phone'.tr(),                    style: TextStyle(                      fontSize: 16,                      fontWeight: FontWeight.bold,                      color: Theme.of(context).brightness == Brightness.dark ? Colors.green.shade300 : Colors.green,                    ),                  ),                  Spacer(),                  if(onDeleted != null)                    IconButton(onPressed: onDeleted, icon: Icon(Icons.delete_outline_rounded, color: Theme.of(context).colorScheme.error))                ],              ),            ),            Padding(              padding: const EdgeInsets.all(16.0),              child: Column(                crossAxisAlignment: CrossAxisAlignment.start,                children: [                  Text(                    phoneNumber,                    style: TextStyle(                      fontSize: 18,                      fontWeight: FontWeight.bold,                      color: Theme.of(context).colorScheme.onSurface,                    ),                  ),                  const SizedBox(height: 16),                  Wrap(                    spacing: 8,                    runSpacing: 8,                    alignment: WrapAlignment.start,                    children: [                      ElevatedButton.icon(                        icon: Icon(Icons.call),                        label: Text('nfc.scan.call'.tr()),                        onPressed: () => launchUrlString('tel:$phoneNumber'),                        style: ElevatedButton.styleFrom(                        ),                      ),                      OutlinedButton.icon(                        icon: Icon(Icons.message),                        label: Text('nfc.scan.message'.tr()),                        onPressed: () => launchUrlString('sms:$phoneNumber'),                      ),                      OutlinedButton.icon(                        icon: Icon(Icons.copy),                        label: Text('nfc.scan.copy'.tr()),                        onPressed: () => Clipboard.setData(ClipboardData(text: phoneNumber)),                      ),                    ],                  ),                ],              ),            ),          ],        ),      ),    ],  );}// E-posta adresi için özel tasarım oluşturan metodWidget buildEmailRecord(BuildContext context, String email,[VoidCallback? onDeleted]) {  return Column(    mainAxisSize: MainAxisSize.min,    children: [      Container(        margin: const EdgeInsets.symmetric(vertical: 6),        clipBehavior: Clip.antiAlias,        decoration: BoxDecoration(          color: Theme.of(context).colorScheme.surfaceContainerLow,          borderRadius: BorderRadius.circular(20),          border: Border.all(            color: Theme.of(context).colorScheme.outlineVariant.withValues(alpha: 0.6),          ),        ),        child: Column(          children: [            Container(              padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),              decoration: BoxDecoration(                color: Colors.transparent,              ),              child: Row(                children: [                  Icon(Icons.email, color: Colors.amber),                  const SizedBox(width: 12),                  Text(                    'nfc.scan.email'.tr(),                    style: TextStyle(                      fontSize: 16,                      fontWeight: FontWeight.bold,                      color: Theme.of(context).brightness == Brightness.dark ? Colors.amber.shade300 : Colors.amber,                    ),                  ),                  Spacer(),                  if(onDeleted != null)                    IconButton(onPressed: onDeleted, icon: Icon(Icons.delete_outline_rounded, color: Theme.of(context).colorScheme.error))                ],              ),            ),            Padding(              padding: const EdgeInsets.all(16.0),              child: Column(                crossAxisAlignment: CrossAxisAlignment.start,                children: [                  Text(                    email,                    style: TextStyle(                      fontSize: 16,                      color: Theme.of(context).colorScheme.onSurface,                    ),                  ),                  const SizedBox(height: 16),                  Wrap(                    spacing: 8,                    runSpacing: 8,                    alignment: WrapAlignment.start,                    children: [                      ElevatedButton.icon(                        icon: Icon(Icons.mail),                        label: Text('nfc.scan.send_email'.tr()),                        onPressed: () => launchUrlString('mailto:$email'),                        style: ElevatedButton.styleFrom(                        ),                      ),                      OutlinedButton.icon(                        icon: Icon(Icons.copy),                        label: Text('nfc.scan.copy'.tr()),                        onPressed: () => Clipboard.setData(ClipboardData(text: email)),                      ),                    ],                  ),                ],              ),            ),          ],        ),      ),    ],  );}// Konum bilgisi için özel tasarım oluşturan metodWidget buildLocationRecord(BuildContext context, String geoUrl,[VoidCallback? onDeleted]) {  // geo:latitude,longitude  String locationText = geoUrl;  String latitude = '';  String longitude = '';  // geo: formatını ayrıştır  if (geoUrl.startsWith('geo:')) {    final coords = geoUrl.substring(4).split(',');    if (coords.length >= 2) {      latitude = coords[0];      longitude = coords[1];      locationText = '$latitude, $longitude';    }  }  return Column(    mainAxisSize: MainAxisSize.min,    children: [      Container(        margin: const EdgeInsets.symmetric(vertical: 6),        clipBehavior: Clip.antiAlias,        decoration: BoxDecoration(          color: Theme.of(context).colorScheme.surfaceContainerLow,          borderRadius: BorderRadius.circular(20),          border: Border.all(            color: Theme.of(context).colorScheme.outlineVariant.withValues(alpha: 0.6),          ),        ),        child: Column(          children: [            Container(              padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),              decoration: BoxDecoration(                color: Colors.transparent,              ),              child: Row(                children: [                  Icon(Icons.location_on, color: Colors.red),                  const SizedBox(width: 12),                  Text(                    'nfc.scan.location'.tr(),                    style: TextStyle(                      fontSize: 16,                      fontWeight: FontWeight.bold,                      color: Theme.of(context).brightness == Brightness.dark ? Colors.red.shade300 : Colors.red,                    ),                  ),                  Spacer(),                  if(onDeleted != null)                    IconButton(onPressed: onDeleted, icon: Icon(Icons.delete_outline_rounded, color: Theme.of(context).colorScheme.error))                ],              ),            ),            Padding(              padding: const EdgeInsets.all(16.0),              child: Column(                crossAxisAlignment: CrossAxisAlignment.start,                children: [                  Text(                    locationText,                    style: TextStyle(                      fontSize: 16,                      color: Theme.of(context).colorScheme.onSurface,                    ),                  ),                  const SizedBox(height: 16),                  Wrap(                    spacing: 8,                    runSpacing: 8,                    alignment: WrapAlignment.start,                    children: [                      ElevatedButton.icon(                        icon: Icon(Icons.map),                        label: Text('nfc.scan.open_map'.tr()),                        onPressed: () {                          // Google Maps URL formatı                          final mapUrl = 'https://www.google.com/maps/search/?api=1&query=$latitude,$longitude';                          launchUrlString(mapUrl);                        },                        style: ElevatedButton.styleFrom(                        ),                      ),                      OutlinedButton.icon(                        icon: Icon(Icons.copy),                        label: Text('nfc.scan.copy'.tr()),                        onPressed: () => Clipboard.setData(ClipboardData(text: locationText)),                      ),                    ],                  ),                ],              ),            ),          ],        ),      ),    ],  );}// SMS bilgisi için özel tasarım oluşturan metodWidget buildSmsRecord(BuildContext context, String smsUrl,[VoidCallback? onDeleted]) {  // sms:phone?body=message  String phoneNumber = '';  String message = '';  // sms: formatını ayrıştır  if (smsUrl.startsWith('sms:')) {    final parts = smsUrl.substring(4).split('?');    if (parts.isNotEmpty) {      phoneNumber = parts[0];      if (parts.length > 1 && parts[1].startsWith('body=')) {        message = Uri.decodeComponent(parts[1].substring(5));      }    }  }  return Column(    mainAxisSize: MainAxisSize.min,    children: [      Container(        margin: const EdgeInsets.symmetric(vertical: 6),        clipBehavior: Clip.antiAlias,        decoration: BoxDecoration(          color: Theme.of(context).colorScheme.surfaceContainerLow,          borderRadius: BorderRadius.circular(20),          border: Border.all(            color: Theme.of(context).colorScheme.outlineVariant.withValues(alpha: 0.6),          ),        ),        child: Column(          children: [            Container(              padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),              decoration: BoxDecoration(                color: Colors.transparent,              ),              child: Row(                children: [                  Icon(Icons.message, color: Colors.purple),                  const SizedBox(width: 12),                  Text(                    'nfc.scan.sms'.tr(),                    style: TextStyle(                      fontSize: 16,                      fontWeight: FontWeight.bold,                      color: Theme.of(context).brightness == Brightness.dark ? Colors.purple.shade300 : Colors.purple,                    ),                  ),                  Spacer(),                  if(onDeleted != null)                    IconButton(onPressed: onDeleted, icon: Icon(Icons.delete_outline_rounded, color: Theme.of(context).colorScheme.error))                ],              ),            ),            Padding(              padding: const EdgeInsets.all(16.0),              child: Column(                crossAxisAlignment: CrossAxisAlignment.start,                children: [                  if (phoneNumber.isNotEmpty)                    ListTile(                      contentPadding: EdgeInsets.zero,                      leading: Icon(Icons.phone, color: Colors.purple),                      title: Text('nfc.scan.phone'.tr()),                      subtitle: Text(phoneNumber),                      dense: true,                    ),                  if (message.isNotEmpty)                    ListTile(                      contentPadding: EdgeInsets.zero,                      leading: Icon(Icons.chat, color: Colors.purple),                      title: Text('nfc.scan.message_content'.tr()),                      subtitle: Text(message),                      dense: true,                    ),                  const SizedBox(height: 16),                  Wrap(                    spacing: 8,                    runSpacing: 8,                    alignment: WrapAlignment.start,                    children: [                      ElevatedButton.icon(                        icon: Icon(Icons.send),                        label: Text('nfc.scan.send_sms'.tr()),                        onPressed: () => launchUrlString(smsUrl),                        style: ElevatedButton.styleFrom(                        ),                      ),                      OutlinedButton.icon(                        icon: Icon(Icons.copy),                        label: Text('nfc.scan.copy'.tr()),                        onPressed: () => Clipboard.setData(ClipboardData(text: message.isNotEmpty ? message : phoneNumber)),                      ),                    ],                  ),                ],              ),            ),          ],        ),      ),    ],  );}// SMS bilgisi için özel tasarım oluşturan metodWidget buildUrlRecord(BuildContext context, String url,[VoidCallback? onDeleted]) {  return Column(    mainAxisSize: MainAxisSize.min,    children: [      Container(        margin: const EdgeInsets.symmetric(vertical: 6),        clipBehavior: Clip.antiAlias,        decoration: BoxDecoration(          color: Theme.of(context).colorScheme.surfaceContainerLow,          borderRadius: BorderRadius.circular(20),          border: Border.all(            color: Theme.of(context).colorScheme.outlineVariant.withValues(alpha: 0.6),          ),        ),        child: Column(          children: [            Container(              padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),              decoration: BoxDecoration(                color: Colors.transparent,              ),              child: Row(                children: [                  Icon(Icons.link, color: Colors.blue),                  const SizedBox(width: 12),                  Text(                    'nfc.scan.url'.tr(),                    style: TextStyle(                      fontSize: 16,                      fontWeight: FontWeight.bold,                      color: Theme.of(context).brightness == Brightness.dark ? Colors.blue.shade300 : Colors.blue,                    ),                  ),                  Spacer(),                  if(onDeleted != null)                    IconButton(onPressed: onDeleted, icon: Icon(Icons.delete_outline_rounded, color: Theme.of(context).colorScheme.error))                ],              ),            ),            Padding(              padding: const EdgeInsets.all(16.0),              child: Column(                crossAxisAlignment: CrossAxisAlignment.start,                children: [                  Text(                    url,                    style: TextStyle(                      fontSize: 16,                      color: Theme.of(context).colorScheme.onSurface,                    ),                  ),                  const SizedBox(height: 16),                  Wrap(                    spacing: 8,                    runSpacing: 8,                    alignment: WrapAlignment.start,                    children: [                      ElevatedButton.icon(                        icon: Icon(Icons.open_in_browser),                        label: Text('nfc.scan.open'.tr()),                        onPressed: () => launchUrlString(url),                        style: ElevatedButton.styleFrom(                        ),                      ),                      OutlinedButton.icon(                        icon: Icon(Icons.copy),                        label: Text('nfc.scan.copy'.tr()),                        onPressed: () => Clipboard.setData(ClipboardData(text: url)),                      ),                    ],                  ),                ],              ),            ),          ],        ),      ),    ],  );}// Metin kaydı için özel tasarım oluşturan metodWidget buildTextRecord(BuildContext context, String text,[VoidCallback? onDeleted]) {  return Column(    mainAxisSize: MainAxisSize.min,    children: [      Container(        margin: const EdgeInsets.symmetric(vertical: 6),        clipBehavior: Clip.antiAlias,        decoration: BoxDecoration(          color: Theme.of(context).colorScheme.surfaceContainerLow,          borderRadius: BorderRadius.circular(20),          border: Border.all(            color: Theme.of(context).colorScheme.outlineVariant.withValues(alpha: 0.6),          ),        ),        child: Column(          children: [            Container(              padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),              decoration: BoxDecoration(                color: Colors.transparent,              ),              child: Row(                children: [                  Icon(Icons.text_fields, color: Colors.green),                  const SizedBox(width: 12),                  Text(                    'nfc.scan.text'.tr(),                    style: TextStyle(                      fontSize: 16,                      fontWeight: FontWeight.bold,                      color: Theme.of(context).brightness == Brightness.dark ? Colors.green.shade300 : Colors.green,                    ),                  ),                  Spacer(),                  if(onDeleted != null)                    IconButton(onPressed: onDeleted, icon: Icon(Icons.delete_outline_rounded, color: Theme.of(context).colorScheme.error))                ],              ),            ),            Padding(              padding: const EdgeInsets.all(16.0),              child: Column(                crossAxisAlignment: CrossAxisAlignment.start,                children: [                  Text(                    text,                    style: TextStyle(                      fontSize: 16,                      color: Theme.of(context).colorScheme.onSurface,                    ),                  ),                  const SizedBox(height: 16),                  Row(                    mainAxisAlignment: MainAxisAlignment.end,                    children: [                      OutlinedButton.icon(                        icon: Icon(Icons.copy),                        label: Text('nfc.scan.copy'.tr()),                        onPressed: () => Clipboard.setData(ClipboardData(text: text)),                      ),                    ],                  ),                ],              ),            ),          ],        ),      ),    ],  );}// Metin kaydı için özel tasarım oluşturan metodWidget buildWifiRecord(BuildContext context, String text,[VoidCallback? onDeleted]) {  // WiFi bilgilerini ayrıştır  final wifiData = parseWifiData(text);  return Column(    mainAxisSize: MainAxisSize.min,    children: [      Container(        margin: const EdgeInsets.symmetric(vertical: 6),        clipBehavior: Clip.antiAlias,        decoration: BoxDecoration(          color: Theme.of(context).colorScheme.surfaceContainerLow,          borderRadius: BorderRadius.circular(20),          border: Border.all(            color: Theme.of(context).colorScheme.outlineVariant.withValues(alpha: 0.6),          ),        ),        child: Column(          children: [            Container(              padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),              decoration: BoxDecoration(                color: Colors.transparent,              ),              child: Row(                children: [                  Icon(Icons.wifi, color: Colors.teal),                  const SizedBox(width: 12),                  Text(                    'nfc.scan.wifi'.tr(),                    style: TextStyle(                      fontSize: 16,                      fontWeight: FontWeight.bold,                      color: Theme.of(context).brightness == Brightness.dark ? Colors.teal.shade300 : Colors.teal,                    ),                  ),                  Spacer(),                  if(onDeleted != null)                    IconButton(onPressed: onDeleted, icon: Icon(Icons.delete_outline_rounded, color: Theme.of(context).colorScheme.error))                ],              ),            ),            Padding(              padding: const EdgeInsets.all(16.0),              child: Column(                crossAxisAlignment: CrossAxisAlignment.start,                children: [                  ListTile(                    leading: Icon(Icons.wifi, color: Colors.teal),                    title: Text('nfc.scan.wifi_name'.tr()),                    subtitle: Text(wifiData['S'] ?? 'Unknown'),                    dense: true,                  ),                  ListTile(                    leading: Icon(Icons.security, color: Colors.teal),                    title: Text('nfc.scan.wifi_security'.tr()),                    subtitle: Text(wifiData['T'] ?? 'Unknown'),                    dense: true,                  ),                  if (wifiData['P'] != null)                    ListTile(                      leading: Icon(Icons.password, color: Colors.teal),                      title: Text('nfc.scan.wifi_password'.tr()),                      subtitle: Text(wifiData['P'] ?? ''),                      dense: true,                    ),                  const SizedBox(height: 16),                  Wrap(                    spacing: 8,                    runSpacing: 8,                    alignment: WrapAlignment.start,                    children: [                      ElevatedButton.icon(                        icon: Icon(Icons.wifi),                        label: Text('nfc.scan.connect_wifi'.tr()),                        onPressed: () {                          // WiFi bağlantısı için platform-spesifik kod gerekebilir                          connectToWifi(wifiData);                        },                        style: ElevatedButton.styleFrom(                        ),                      ),                      OutlinedButton.icon(                        icon: Icon(Icons.share),                        label: Text('nfc.scan.share_wifi'.tr()),                        onPressed: () => shareWifiDetails(context,wifiData),                      ),                      const SizedBox(width: 8),                      OutlinedButton.icon(                        icon: Icon(Icons.copy),                        label: Text('nfc.scan.copy'.tr()),                        onPressed: () => Clipboard.setData(ClipboardData(text: text)),                      ),                    ],                  ),                ],              ),            ),          ],        ),      ),    ],  );}// Metin kaydı için özel tasarım oluşturan metodWidget buildVcardRecord(BuildContext context, String content,[VoidCallback? onDeleted]) {  print('VCARD CONTENT: $content');  Map<String, String> contactData = parseVCardData(content);  return Column(    mainAxisSize: MainAxisSize.min,    children: [      Container(        margin: const EdgeInsets.symmetric(vertical: 6),        clipBehavior: Clip.antiAlias,        decoration: BoxDecoration(          color: Theme.of(context).colorScheme.surfaceContainerLow,          borderRadius: BorderRadius.circular(20),          border: Border.all(            color: Theme.of(context).colorScheme.outlineVariant.withValues(alpha: 0.6),          ),        ),        child: Column(          children: [            Container(              padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),              decoration: BoxDecoration(                color: Colors.transparent,              ),              child: Row(                children: [                  Icon(Icons.contact_phone, color: Colors.orange),                  const SizedBox(width: 12),                  Text(                    'nfc.scan.contact'.tr(),                    style: TextStyle(                      fontSize: 16,                      fontWeight: FontWeight.bold,                      color: Theme.of(context).brightness == Brightness.dark ? Colors.orange.shade300 : Colors.orange,                    ),                  ),                  Spacer(),                  if(onDeleted != null)                    IconButton(onPressed: onDeleted, icon: Icon(Icons.delete_outline_rounded, color: Theme.of(context).colorScheme.error))                ],              ),            ),            Padding(              padding: const EdgeInsets.all(16.0),              child: Column(                crossAxisAlignment: CrossAxisAlignment.start,                children: [                  // İsim                  if (contactData['FN'] != null)                    ListTile(                      leading: Icon(Icons.person, color: Colors.orange),                      title: Text('nfc.scan.contact_name'.tr()),                      subtitle: Text(contactData['FN']!),                      dense: true,                    ),                  // Telefon                  if (contactData['TEL'] != null)                    ListTile(                      leading: Icon(Icons.phone, color: Colors.orange),                      title: Text('nfc.scan.contact_phone'.tr()),                      subtitle: Text(contactData['TEL']!),                      dense: true,                      trailing: IconButton(                        icon: Icon(Icons.call),                        onPressed: () {                          final phoneNumber = contactData['TEL']!;                          launchUrlString('tel:$phoneNumber');                        },                      ),                    ),                  // E-posta                  if (contactData['EMAIL'] != null)                    ListTile(                      leading: Icon(Icons.email, color: Colors.orange),                      title: Text('nfc.scan.contact_email'.tr()),                      subtitle: Text(contactData['EMAIL']!),                      dense: true,                      trailing: IconButton(                        icon: Icon(Icons.mail),                        onPressed: () {                          final email = contactData['EMAIL']!;                          launchUrlString('mailto:$email');                        },                      ),                    ),                  // Adres                  if (contactData['ADR'] != null)                    ListTile(                      leading: Icon(Icons.location_on, color: Colors.orange),                      title: Text('nfc.scan.contact_address'.tr()),                      subtitle: Text(contactData['ADR']!),                      dense: true,                      trailing: IconButton(                        icon: Icon(Icons.map),                        onPressed: () {                          final address = contactData['ADR']!;                          launchUrlString('https://maps.google.com/?q=$address');                        },                      ),                    ),                  const SizedBox(height: 16),                  Row(                    mainAxisAlignment: MainAxisAlignment.end,                    children: [                      ElevatedButton.icon(                        icon: Icon(Icons.person_add),                        label: Text('nfc.scan.add_contact'.tr()),                        onPressed: () {                          // Kişi ekleme işlemi platform-spesifik kod gerektirir                          // Şimdilik sadece vCard'ı kopyalayalım                          Clipboard.setData(ClipboardData(text: content));                        },                        style: ElevatedButton.styleFrom(                        ),                      ),                      const SizedBox(width: 8),                      OutlinedButton.icon(                        icon: Icon(Icons.copy),                        label: Text('nfc.scan.copy'.tr()),                        onPressed: () => Clipboard.setData(ClipboardData(text: content)),                      ),                    ],                  ),                ],              ),            ),          ],        ),      ),    ],  );}// Metin kaydı için özel tasarım oluşturan metodWidget buildOtherRecord(BuildContext context, String content,String mimeType,[VoidCallback? onDeleted]) {  return Column(    mainAxisSize: MainAxisSize.min,    children: [      Container(        margin: const EdgeInsets.symmetric(vertical: 6),        clipBehavior: Clip.antiAlias,        decoration: BoxDecoration(          color: Theme.of(context).colorScheme.surfaceContainerLow,          borderRadius: BorderRadius.circular(20),          border: Border.all(            color: Theme.of(context).colorScheme.outlineVariant.withValues(alpha: 0.6),          ),        ),        child: Column(          children: [            Container(              padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),              decoration: BoxDecoration(                color: Colors.transparent,              ),              child: Row(                children: [                  Icon(Icons.data_object, color: Colors.deepPurple),                  const SizedBox(width: 12),                  Expanded(                    child: Text(                      mimeType,                      style: TextStyle(                        fontSize: 16,                        fontWeight: FontWeight.bold,                        color: Theme.of(context).brightness == Brightness.dark ? Colors.deepPurple.shade300 : Colors.deepPurple,                      ),                      overflow: TextOverflow.ellipsis,                    ),                  ),                  Spacer(),                  if(onDeleted != null)                    IconButton(onPressed: onDeleted, icon: Icon(Icons.delete_outline_rounded, color: Theme.of(context).colorScheme.error))                ],              ),            ),            Padding(              padding: const EdgeInsets.all(16.0),              child: Column(                crossAxisAlignment: CrossAxisAlignment.start,                children: [                  Text(                    content,                    style: TextStyle(                      fontSize: 16,                      color: Theme.of(context).colorScheme.onSurface,                    ),                    maxLines: 10,                    overflow: TextOverflow.ellipsis,                  ),                  const SizedBox(height: 16),                  Row(                    mainAxisAlignment: MainAxisAlignment.end,                    children: [                      OutlinedButton.icon(                        icon: Icon(Icons.copy),                        label: Text('nfc.scan.copy'.tr()),                        onPressed: () => Clipboard.setData(ClipboardData(text: content)),                      ),                    ],                  ),                ],              ),            ),          ],        ),      ),      Divider(color: Theme.of(context).dividerColor),    ],  );}